export function applePreview(src:string,progressive=false):CSSProperties | undefined {const preview=previews[src];return preview ? {backgroundImage:progressive?`url("${src.replace('/apple-store/','/apple-store/preview80/')}"), url("${preview}")`:`url("${preview}")`,backgroundPosition:progressive?'center, center':'center',backgroundSize:progressive?'contain, contain':'contain',backgroundRepeat:progressive?'no-repeat, no-repeat':'no-repeat'} : undefined;}
export function clearApplePreview(event:SyntheticEvent<HTMLImageElement>){const image=event.currentTarget,source=image.currentSrc,requested=image.getAttribute('src');const clear=()=>{if(image.isConnected&&image.currentSrc===source&&image.getAttribute('src')===requested&&image.complete&&image.naturalWidth)image.style.backgroundImage='none'};if(typeof image.decode==='function')void image.decode().then(clear).catch(clear);else clear()}
export function fallbackApplePreview(event:SyntheticEvent<HTMLImageElement>,src:string):boolean {const image=event.currentTarget;const preview=previews[src];if(!preview || image.getAttribute('src')===preview)return false;image.removeAttribute('srcset');image.src=preview;return true;}
